#!/bin/sh
# Turns theme/ (the CSS and the ES modules) into c/theme.c, so the ecodoc binary carries its theme
# and a docs build needs nothing but the binary. Run it after editing anything under theme/; the
# build links the C. While working on the theme, ECODOC_THEME=theme reads the files from disk instead.
set -eu
cd "$(dirname "$0")/.."

python3 - <<'PY'
import pathlib

root = pathlib.Path('theme')
files = sorted(p for p in root.rglob('*') if p.is_file() and not p.name.startswith('.'))
out = ['/*',
       ' * The theme ecodoc writes into every site, from theme/.',
       ' * Generated by tools/embed-theme.sh; do not edit.',
       ' */',
       '',
       '#include <stddef.h>',
       '#include <stdint.h>',
       '']
names = []
for i, f in enumerate(files):
    # the published path: theme/js/main.js is assets/main.js
    rel = f.relative_to(root)
    name = rel.name if rel.parts[0] == 'js' else str(rel)
    names.append(name)
    data = f.read_bytes()
    out.append(f'static const unsigned char asset_{i}[] = {{')
    for j in range(0, len(data), 20):
        out.append('    ' + ''.join(f'0x{b:02x},' for b in data[j:j + 20]))
    out.append('    0x00')
    out.append('};')
    out.append('')

out.append('static const char *asset_names[] = {')
for n in names:
    out.append(f'    "{n}",')
out.append('};')
out.append('')
out.append('static const unsigned char *asset_data[] = {')
for i in range(len(files)):
    out.append(f'    asset_{i},')
out.append('};')
out.append('')
out.append('static const uint64_t asset_sizes[] = {')
for i, f in enumerate(files):
    out.append(f'    {f.stat().st_size},')
out.append('};')
out.append('')
out.append(f'int32_t ecodoc_asset_count(void)\n{{\n    return {len(files)};\n}}\n')
out.append('const char *ecodoc_asset_name(int32_t i)\n{\n    return asset_names[i];\n}\n')
out.append('const unsigned char *ecodoc_asset_data(int32_t i)\n{\n    return asset_data[i];\n}\n')
out.append('uint64_t ecodoc_asset_size(int32_t i)\n{\n    return asset_sizes[i];\n}')
pathlib.Path('c/theme.c').write_text('\n'.join(out) + '\n')
print(f'embed-theme: c/theme.c, {len(files)} file(s): {", ".join(names)}')
PY
